cd /app/work && cat > schema.py <<'EOF'
import json, sys, subprocess
sys.path.insert(0,'/app/work')
import gen, gen2, gen3
STATUSES={'accepted','dropped','duplicate','error','buffered'}
REASONS={'OK','AUTH','DUPLICATE','INITIAL_TOO_SMALL','EARLY_REJECTED','KEYS_DISCARDED','BUFFER_FULL',
         'CONNECTION_CLOSED','LAYOUT','NO_KEYS','FRAME_ENCODING_ERROR','PROTOCOL_VIOLATION',
         'STREAM_STATE_ERROR','STREAM_LIMIT_ERROR','FINAL_SIZE_ERROR','FLOW_CONTROL_ERROR','CRYPTO_BUFFER_EXCEEDED'}
CODES=REASONS|{'IDLE_TIMEOUT','PEER_APPLICATION_CLOSE','PEER_TRANSPORT_CLOSE'}
def chk(d):
    assert set(d)=={'version','results'}, d.keys()
    assert d['version']==1
    for r in d['results']:
        assert set(r)=={'id','packets','connection','keys','received_total','streams','crypto'}, r.keys()
        for p in r['packets']:
            assert set(p)=={'event','packet','status','reason','at_ms','frame'}, p
            assert p['status'] in STATUSES, p
            assert p['reason'] in REASONS, p
            assert type(p['at_ms']) is int
            assert p['frame'] is None or type(p['frame']) is int
        c=r['connection']
        assert set(c)=={'state','code','at_ms','source','peer_code','last_activity_ms'}, c
        assert c['state'] in ('open','closed','idle')
        if c['state']=='open':
            assert c['code'] is None and c['at_ms'] is None and c['source'] is None and c['peer_code'] is None
        else:
            assert c['code'] in CODES, c
            assert type(c['at_ms']) is int
            assert set(c['source'])=={'event','packet','frame'}
            assert c['peer_code'] is None or type(c['peer_code']) is int
            if c['code'].startswith('PEER_'): assert type(c['peer_code']) is int, c
            else: assert c['peer_code'] is None, c
        assert set(r['keys'])=={'I','H','Z','A'}
        for v in r['keys'].values(): assert v in ('absent','live','discarded')
        assert type(r['received_total']) is int
        ids=[s['id'] for s in r['streams']]
        assert ids==sorted(ids)
        for s in r['streams']:
            assert set(s)=={'id','highest','final_size','reset','stopped','delivered_hex'}, s
            assert type(s['highest']) is int and type(s['reset']) is bool and type(s['stopped']) is bool
            assert s['final_size'] is None or type(s['final_size']) is int
        assert [c['level'] for c in r['crypto']]==['I','H','A']
        for c in r['crypto']:
            assert set(c)=={'level','highest','contiguous_hex'}
bad=0
for mod in (gen,gen2,gen3):
    for seed in range(400):
        req=mod.gen(seed)
        p=subprocess.run([sys.executable,'-I','/app/submission/entry.py'],input=json.dumps(req).encode(),capture_output=True,cwd='/app/submission')
        d=json.loads(p.stdout)
        if 'results' in d:
            try: chk(d)
            except AssertionError as e:
                print('SCHEMA FAIL',mod.__name__,seed,e); bad+=1; break
print('schema done bad=',bad)
EOF
python3 schema.py
